header>button{background:transparent;color:white;border:0;font-weight:600}nav a{color:#173651;font-size:12px;font-weight:600;margin-left:16px}main{padding-bottom:36px}.guide{border:1px solid #d3e0eb;background:white;border-radius:6px;padding:12px 15px;margin-bottom:18px}.guide>b{display:block;margin-bottom:10px}.guide #guide-items{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px 24px}.guide-item{display:flex;align-items:center;gap:10px}.guide-item strong{display:inline-flex;align-items:center;justify-content:center;min-width:32px;height:30px;background:#fff0d4;color:#945100;border-radius:4px;font-size:11px}.guide-item small{display:block;color:#6c8299;margin-top:2px}.work-table{min-width:1050px}.work-table th{white-space:nowrap;padding:10px 12px}.work-table td{padding:13px 12px;border-bottom:1px solid #dae5ef}.work-table tbody tr:last-child td{border-bottom:0}.work-table tbody tr:hover{background:#edf5fc}.link{padding:0;border:0;background:transparent;color:#2563eb;font-weight:600;text-align:left}.link:hover{text-decoration:underline}.customer-link{color:#173651;font-weight:700}.doc-strip{display:flex;gap:5px;white-space:nowrap}.doc-strip button{height:29px;min-width:29px;padding:4px;background:#f58a00;color:white;border:0;font-weight:700}.doc-strip button.available{background:#2563eb}.plain-status{display:inline-block;padding:4px 9px;border-radius:12px;background:#fff0d4;color:#80530a;white-space:nowrap}.plain-status.blue{background:#dfeaff;color:#164497}.muted{color:#6b8196}.description strong{display:block}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:16px 0}.summary>div{background:white;border:1px solid #c8d9e8;border-radius:6px;padding:14px 16px}.summary span{display:block;color:#6c8197}.summary b{display:block;font-size:22px;margin:7px 0}.summary small{color:#6c8197}.subnav{display:flex;gap:18px;background:white;border:1px solid #c8d9e8;border-radius:6px 6px 0 0;margin-top:18px;padding:0 15px}.subnav button{border:0;border-radius:0;padding:12px 4px}.subnav button.active{border-bottom:3px solid #3766a2;color:#3766a2;font-weight:600}.issue{border:0;background:none;color:#e51b2b;font-size:20px;font-weight:800;line-height:1}.gp-low{color:#e51b2b}.meta{display:flex;gap:24px;flex-wrap:wrap;margin-bottom:15px}.meta span{color:#6c8197}.meta b{color:#203047;margin-left:8px}.empty{text-align:center;padding:36px!important;color:#657e96}#information{width:470px}#information-body{font-size:12px;line-height:1.7}#information-body p{margin:0 0 10px}.selection-bar{display:flex;gap:16px;align-items:center;justify-content:flex-end;background:white;border:1px solid #c8d9e8;padding:12px;margin-top:12px}.action-note{color:#6c8197;font-size:11px}.num{font-variant-numeric:tabular-nums}.tools input[type=search]{flex:1;max-width:560px}.tools select{min-width:220px}.tools span{font-size:11px}table.detail{min-width:1120px}table.detail th,table.detail td{padding:11px 9px}.loading{padding:32px;color:#60788f}#notice:empty{display:none}@media(max-width:900px){.guide #guide-items{grid-template-columns:repeat(2,minmax(0,1fr))}.summary{grid-template-columns:repeat(2,1fr)}.tools select{min-width:170px}nav{gap:10px}nav a{margin-left:0}}@media(max-width:550px){.summary{grid-template-columns:1fr 1fr}.guide #guide-items{grid-template-columns:1fr}.summary b{font-size:19px}}

#booking{width:420px}#booking fieldset{border:0;padding:0;margin:0}#booking legend{font-weight:600;margin-bottom:10px}#booking fieldset>label{display:flex;gap:10px;align-items:center;margin:10px 0}#booking .date-label{display:block;margin-top:20px}#booking-date{display:block;width:100%;margin-top:7px}#booking-status{color:#b4232d;font-size:12px;margin-bottom:0}#booking .primary{background:#2563eb;color:white;border-color:#2563eb}#booking fieldset:disabled{opacity:.65}

#invoice-review{width:680px}#invoice-review table{min-width:0}#invoice-review fieldset{border:0;padding:0;margin:18px 0 0}#invoice-number{display:block;width:260px;margin-top:6px}.invoice-qty{width:80px;text-align:right}.invoice-total{text-align:right;font-size:16px;font-weight:700;margin-top:16px}#invoice-status{color:#b4232d}#invoice-review .primary{background:#2563eb;color:white;border-color:#2563eb}#invoice-withdraw{margin-right:auto;color:#b4232d}#invoice-review footer{flex-wrap:wrap}.select-all{margin-right:auto;display:flex;gap:6px;align-items:center}

#documents{width:480px}#documents fieldset{border:0;margin:16px 0 0;padding:0}#documents fieldset>label{display:block;font-weight:600;margin-top:12px}#documents input,#documents select{display:block;width:100%;margin-top:5px}#documents input[type=file]{padding:8px;background:#f5f8fc;border:1px solid #c8d9e8;border-radius:4px}#documents fieldset>small{display:block;margin-top:8px;color:#647991}#document-status{color:#b4232d}.document-item{padding:9px 0;border-bottom:1px solid #e1e9f0}.document-item small{display:block;color:#71839a;margin-top:3px}#documents .primary{background:#2563eb;color:white;border-color:#2563eb}

.invoice-heading{display:flex;justify-content:space-between;align-items:center}.invoice-heading h2{font-size:18px}#information:has(.invoice-heading){width:760px}#information table{min-width:0}#print-invoice{padding:24px}#print-invoice table{width:100%;min-width:0}@media print{body.printing-invoice>*{display:none!important}body.printing-invoice>#print-invoice{display:block!important}#print-invoice{background:white;color:#173651}#print-invoice th{background:#e4edf6}#print-invoice td,#print-invoice th{padding:10px;border-bottom:1px solid #d3e0eb}}

.selection-cell{white-space:nowrap}.row-drag{display:inline-flex;vertical-align:middle;padding:0 7px 0 0;border:0;background:none;color:#3766a2;font-size:19px;line-height:1;cursor:grab}.row-drag:active{cursor:grabbing}tr[data-task]{transition:background .12s}

/* SUPPORT presentation follows the existing Purchase shell and shared MASTER type roles.
   Keep all existing IDs, controls, document states and business handlers. */
body.support-workroom{font-family:var(--master-font);font-size:11px;line-height:1.4;background:#f3f6f9;color:#203047}
body.support-workroom>header{height:49px;min-height:49px;padding:0 24px;gap:18px;background:#133858;color:#fff;font:12px/1.3 var(--master-font);position:sticky;top:0;z-index:30}
body.support-workroom>header .brand{font:700 20px/1 var(--master-font);letter-spacing:.3px;white-space:nowrap}
body.support-workroom>header .department{border-left:1px solid #446781;padding-left:18px;font:500 13px/1.3 var(--master-font);white-space:nowrap}
body.support-workroom>header select{height:32px;min-height:32px;min-width:240px;max-width:280px;padding:0 40px 0 12px;background:#fff;color:#203047;font:600 12px/1.3 var(--master-font)}
body.support-workroom>header #staff{font:400 11px/1.3 var(--master-font);white-space:nowrap}
body.support-workroom>header #refresh{min-height:32px;padding:6px 0;font:500 11px/1.3 var(--master-font);color:#fff}
body.support-workroom>nav{height:42px;padding:0 20px;gap:24px;position:sticky;top:49px;z-index:29;font-size:12px;line-height:normal}
body.support-workroom>nav :is(button,a){height:42px;display:inline-flex;align-items:center;padding:0 2px;margin:0;font:600 12px var(--master-font);color:#203047;text-decoration:none;white-space:nowrap}
body.support-workroom>nav button.active{color:#3766a2;border-bottom:3px solid #3766a2}
body.support-workroom>nav a:hover{text-decoration:underline;color:#2563eb}
body.support-workroom>main{padding:18px 20px 36px;max-width:none}
body.support-workroom .heading{min-height:56px;margin-bottom:18px}
body.support-workroom h1{font:800 20px/26px var(--master-font);margin:0 0 5px}
body.support-workroom .heading p{font:400 12px/18px var(--master-font);color:#647b93}
body.support-workroom .guide{padding:12px 15px;margin-bottom:14px;border-color:#cbdced}
body.support-workroom .guide>b{font-weight:700;color:#203047}
body.support-workroom .guide-item strong{height:28px;min-width:28px;border-radius:5px;font:700 11px/1 var(--master-font)}
body.support-workroom .guide-item span{font-size:11px;line-height:15px}
body.support-workroom .tools{padding:9px 12px;gap:12px;margin-bottom:12px;border-color:#cbdced}
body.support-workroom .tools :is(select,input){height:32px;font-size:11px}
body.support-workroom .tools span{font-size:11px}
body.support-workroom .table-frame{border-color:#b9d0e4;border-radius:6px}
body.support-workroom .work-table th{height:32px;padding:7px 8px;font:700 11px/15.4px var(--master-font);color:#203047;background:#d2dfea}
body.support-workroom .work-table td{height:44px;padding:6px 8px;font:400 11px/14px var(--master-font);color:#203047;border-color:#d4e2ef}
body.support-workroom .work-table td small{font:400 10px/14px var(--master-font);margin-top:2px;color:#647b93}
body.support-workroom .work-table .num{font-weight:600;font-variant-numeric:tabular-nums}
body.support-workroom .work-table .description strong{font:700 11px/14px var(--master-font);color:#173557}
body.support-workroom .work-table .description small{margin:0}
body.support-workroom table.detail td{height:51px;padding:3px 8px}
body.support-workroom .doc-strip button{height:28px;min-width:28px;padding:4px;border-radius:5px;font:700 11px/1 var(--master-font)}
body.support-workroom .link{font:600 11px/14px var(--master-font);color:#2563eb}
body.support-workroom [data-shipment]:not(:has(small)){color:#f58a00;font-size:18px}
body.support-workroom .plain-status{font:600 11px/14px var(--master-font);padding:3px 8px}
body.support-workroom .meta{margin:0;padding:12px 16px;border-bottom:1px solid #d4e2ef;background:#f5f9fd;font-size:11px}
body.support-workroom .selection-bar{margin-top:0;padding:10px 12px;border:0;border-top:1px solid #d4e2ef}
body.support-workroom .selection-bar button{min-height:30px;font-size:11px}
body.support-workroom .subnav{margin-top:14px}
body.support-workroom .subnav button{font-size:12px;font-weight:600}
body.support-workroom .summary>div{padding:12px 15px}
body.support-workroom .summary b{font:800 20px/26px var(--master-font)}
body.support-workroom dialog{font:400 11px/1.5 var(--master-font);border-color:#b4cce1;border-radius:8px}
body.support-workroom dialog .dialog-header{padding:14px 16px;background:#dceaf7}
body.support-workroom dialog .dialog-header h2{font:700 14px/20px var(--master-font);margin:0}
body.support-workroom dialog .dialog-body{padding:16px}
body.support-workroom dialog footer{padding:12px 16px;background:#f5f9fd;gap:10px}
body.support-workroom :is(#booking,#documents,#invoice-review) .primary{background:#3766a2;border-color:#3766a2;color:#fff;font-weight:600}
body.support-workroom :is(#booking,#documents,#invoice-review) button.primary:disabled{background:#e8eef3;border-color:#d5e0e9;color:#8292a3;cursor:not-allowed}
body.support-workroom .doc-strip button:hover:not(:disabled){transform:translateY(-1px);box-shadow:0 2px 5px #17365124}
@media(max-width:800px){body.support-workroom>header{height:auto;min-height:49px;padding:10px 12px;gap:10px;flex-wrap:wrap;position:static}body.support-workroom>header .brand{font-size:16px}body.support-workroom>header .department{font-size:12px;padding-left:10px}body.support-workroom>header select{min-width:190px;max-width:220px;margin-left:auto}body.support-workroom>nav{position:static;overflow-x:auto;gap:18px;padding:0 12px;flex-shrink:0}body.support-workroom>nav a{display:inline-flex}body.support-workroom>main{padding:18px 12px 36px}body.support-workroom .heading{min-height:0}body.support-workroom .tools input[type=search]{min-width:150px;max-width:100%}}
@media(max-width:560px){body.support-workroom>header select{margin-left:0;width:190px}body.support-workroom .tools select{min-width:150px}body.support-workroom .guide #guide-items{grid-template-columns:repeat(2,minmax(0,1fr))}body.support-workroom .meta{gap:8px 16px}}
@media(prefers-reduced-motion:reduce){body.support-workroom .doc-strip button:hover:not(:disabled){transform:none}}

/* Three workroom views retain the Purchase shell, typography and status palette. */
.order-count{border:0;border-radius:16px;background:#f58a00;color:#fff;min-width:29px;height:25px;font:700 11px var(--master-font)}.zero-count{color:#8292a3}.icon-link{display:inline-flex;align-items:center;justify-content:center;background:none;border:0;color:#2563eb;padding:4px}.icon-link svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.icon-link:disabled{color:#b8c4d0;cursor:not-allowed}.icon-link:not(:disabled):hover{transform:translateY(-1px)}.plain-status.neutral{background:#e8eef3;color:#60778b}.shipment-edit{margin-left:8px}.work-table.order-tasks{min-width:850px}.order-tasks td:nth-child(3){min-width:210px}.order-tasks td:nth-child(4){min-width:270px}.order-tasks td:nth-last-child(-n+2){width:130px}.selection-bar .primary,#profile-save{background:#3766a2;border:1px solid #3766a2;color:#fff}.selection-bar .primary:disabled{background:#e8eef3;color:#8292a3;border-color:#d5e0e9;cursor:not-allowed}#customer-profile{width:560px}#profile-fields{border:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:12px 16px}#profile-fields label{display:block;font-weight:600}#profile-fields input,#profile-fields select{display:block;width:100%;margin-top:5px;min-height:32px}#profile-status{font-size:11px;color:#647b93}#profile-identity{font-weight:700;margin:0 0 16px}#profile-fields:disabled{opacity:.65}#order-filter{max-width:250px}.tools #customer-filter{min-width:270px}@media(max-width:550px){#profile-fields{grid-template-columns:1fr}.tools #customer-filter{min-width:150px}.selection-bar{flex-wrap:wrap}.selection-bar .action-note{max-width:200px}}

/* Customer task list; numeric measures retain Purchase typography. */
.work-table.order-tasks{min-width:1280px;table-layout:auto}.order-tasks td:nth-child(3){min-width:250px}.order-tasks td:nth-child(4){min-width:80px}.order-tasks td:nth-last-child(-n+2){width:auto}.order-tasks .price-cell span{display:block;line-height:17px}.order-tasks td:nth-child(11){min-width:190px}.order-tasks td:nth-child(10){white-space:nowrap}.customer-task-meta>strong{width:100%;font-size:16px;color:#173557}.order-tasks .issue{font-size:19px}#order-filter{min-width:170px;max-width:200px}

/* Approved customer Desk workroom, scoped to Orders only. */
body.support-orders-view .heading{display:none}
body.support-orders-view .tools{padding:0;background:none;border:0;margin-bottom:12px}
body.support-orders-view .tools #search,body.support-orders-view .tools #order-filter,body.support-orders-view .tools #count{display:none}
body.support-orders-view #content{border:0;border-radius:0;background:transparent;overflow:visible}
.desk-header{background:#fff;border:1px solid #bfd2e5;border-radius:6px;overflow:hidden;color:#173557}
.desk-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 20px 16px;border-bottom:1px solid #dce6ef;flex-wrap:wrap}
.desk-heading>div>small{display:block;color:#647b93;font-size:10px;letter-spacing:.3px;margin-bottom:5px}
.desk-heading h2{font:800 20px/26px var(--master-font);margin:0;overflow-wrap:anywhere}
.desk-navigation{min-width:152px;text-align:center}.desk-navigation>small{display:block;margin-top:5px;font-size:10px;color:#647b93}
.desk-switcher{display:flex;align-items:center;border:1px solid #bfd2e5;border-radius:5px;background:#f5f9fd;overflow:hidden}
.desk-switcher button{background:none;border:0;color:#2563eb;font-size:20px;line-height:1;width:32px;min-height:32px;padding:0}
.desk-switcher button:disabled{color:#aabdd5;cursor:not-allowed}.desk-switcher b{font-size:14px;min-width:86px;padding:0 4px}
.desk-groups{display:grid;grid-template-columns:1fr 1.2fr 1fr;gap:20px;padding:18px 20px}
.desk-groups>section{min-width:0}.desk-groups>section+section{padding-left:20px;border-left:1px solid #dce6ef}
.desk-groups h3{font:600 10px/15px var(--master-font);letter-spacing:.6px;color:#526e8a;margin:0 0 13px}
.desk-groups dl{display:grid;grid-template-columns:auto minmax(0,1fr);gap:9px 14px;margin:0;align-items:baseline}
.desk-groups dt{color:#647b93;font-size:11px}.desk-groups dd{font-size:11px;font-weight:600;margin:0;overflow-wrap:anywhere}
.desk-groups .desk-edit{margin-top:12px}.desk-totals dd{text-align:right;font-size:16px;font-variant-numeric:tabular-nums;white-space:nowrap}
.desk-totals dd small{font:400 10px/14px var(--master-font);color:#647b93}.desk-amount{border-top:1px solid #dce6ef;margin-top:10px;padding-top:10px;text-align:right}
.desk-amount>span{display:block;color:#647b93;font-size:10px}.desk-amount>strong{display:block;font:700 22px/30px var(--master-font);font-variant-numeric:tabular-nums}
.desk-amount>strong>small{font:400 10px/14px var(--master-font);color:#647b93}
.desk-scope{display:block;text-align:right;color:#647b93;font:400 10px/14px var(--master-font);margin-top:4px}
.desk-invoice-action{text-align:right;margin-top:12px}.desk-invoice-action .primary{background:#3766a2;border:1px solid #3766a2;color:#fff;font:600 11px/15px var(--master-font);padding:7px 12px;min-height:30px}
.desk-invoice-action .primary:disabled{background:#e8eef3;border-color:#d5e0e9;color:#8292a3;cursor:not-allowed}.desk-retry{display:block;margin-top:8px;margin-left:auto}
.desk-task-table{overflow-x:auto;border:1px solid #b9d0e4;border-radius:6px;background:#fff;margin-top:12px}
body.support-workroom .desk-task-table table.order-tasks{min-width:1080px}.desk-task-table .order-tasks :is(th,td):first-child{width:50px;text-align:center;min-width:50px;padding-left:6px;padding-right:6px}
.desk-cell select{width:38px!important;min-width:38px;max-width:38px;font:600 11px/14px var(--master-font);color:#2563eb;min-height:28px;padding:4px 1px 4px 4px;background:#fff;border:1px solid #b7cde3;border-radius:4px}
.desk-cell select:disabled{color:#8292a3;background:#eef3f7;cursor:not-allowed}.desk-description{display:flex;align-items:center;gap:5px}.desk-description .row-drag{font-size:17px;flex:0 0 auto;padding-right:0}
.desk-task-table .order-tasks td:nth-child(2){min-width:220px}.desk-task-table .order-tasks td:nth-child(3){min-width:75px}.desk-task-table .order-tasks td:nth-child(4){min-width:75px}.desk-task-table .order-tasks td:nth-child(9){white-space:nowrap}.desk-task-table .order-tasks td:nth-child(10){min-width:190px;white-space:normal}
#booking-arrival{display:block;width:100%;margin-top:7px}#booking .date-label[hidden]{display:none}
@media(max-width:800px){.desk-groups{grid-template-columns:1fr 1.2fr}.desk-groups .desk-totals{grid-column:1/-1;border-left:0;border-top:1px solid #dce6ef;padding:14px 0 0}.desk-totals dl{grid-template-columns:auto auto auto auto}.desk-amount{display:flex;justify-content:space-between;align-items:baseline}.desk-invoice-action{text-align:right}}
@media(max-width:500px){.desk-heading{padding:16px}.desk-heading h2{font-size:18px}.desk-groups{grid-template-columns:1fr;padding:16px;gap:14px}.desk-groups>section+section{border-left:0;border-top:1px solid #dce6ef;padding:14px 0 0}.desk-totals dl{grid-template-columns:auto auto}.desk-navigation{min-width:152px}}

/* Approved compact shipment header. Existing Purchase type roles and business controls remain authoritative. */
body.support-orders-view .tools{display:none}
body.support-workroom>nav .orders-tab{height:42px;display:none;align-items:center;padding:0 2px;font:600 12px var(--master-font);color:#203047;white-space:nowrap}
body.support-workroom>nav .orders-tab.active{color:#3766a2;border-bottom:3px solid #3766a2}
.customer-order-entry{display:inline-flex;align-items:center;gap:7px;background:transparent;border:0;color:#2563eb;font:600 11px var(--master-font);padding:0}
.customer-order-entry .order-count{display:inline-flex;align-items:center;justify-content:center}
.customer-order-entry svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.shipment-header .desk-heading{padding:13px 15px 9px;align-items:flex-start;flex-wrap:nowrap;min-height:0}
.shipment-header .desk-heading h2{margin:0 0 6px}
.shipment-header .desk-switcher{display:inline-flex;width:116px}
.shipment-header .desk-switcher b{font-size:12px;min-width:54px}
.shipment-header .desk-switcher button{width:28px;min-height:28px}
.shipment-invoice{display:flex;justify-content:flex-end;align-items:center;gap:8px;flex-wrap:wrap;padding-top:3px;font-size:11px}
.shipment-invoice>small{color:#647b93;font-size:10px}
.shipment-invoice .invoice-number-link{color:#2563eb;background:#f5f9fd;border:1px solid #b7cde3;border-radius:4px;padding:5px 8px;font:600 11px var(--master-font)}
.shipment-invoice .invoice-number-link:disabled{color:#8292a3;background:#eef3f7;cursor:not-allowed}
.shipment-columns{display:grid;grid-template-columns:1fr 1.05fr 1.65fr 1fr;gap:0}
.shipment-columns>section{min-width:0;padding:16px 20px 18px}
.shipment-columns>section+section{border-left:1px solid #dce6ef}
.shipment-detail-group{display:grid;gap:6px}
.shipment-detail-group+.shipment-detail-group{margin-top:9px}
.shipment-kv{display:grid;grid-template-columns:92px minmax(0,1fr);gap:5px;align-items:center;min-height:23px}
.shipment-kv>span{color:#647b93;font-size:11px}
.shipment-kv>strong{font-weight:600;font-size:11px;overflow-wrap:anywhere}
.shipment-kv .shipment-field{display:inline-flex;align-items:center;gap:5px;justify-self:start;padding:0;border:0;background:transparent;text-align:left;color:#173557;font:600 11px var(--master-font);min-width:0}
.shipment-field>b{font-weight:600;overflow-wrap:anywhere}.shipment-field>.edit-pencil{color:#2563eb;font-size:13px;flex-shrink:0}
