.support-customers-view .tools{display:none}
.support-customers-view .work-table tbody tr:not([data-customer-row]):hover{background:transparent}
tr[data-customer-row]{cursor:pointer}
tr[data-customer-row]:is(:hover,:focus-within)>td{background:#f6faff}
tr[data-customer-row]:hover .customer-order-entry svg,.customer-order-entry:focus-visible svg{transform:translateX(3px)}
@media(prefers-reduced-motion:reduce){tr[data-customer-row] .customer-order-entry svg{transition:none;transform:none!important}}
.invoice-toolbar{grid-template-columns:minmax(0,1fr) auto;gap:4px 10px;padding:4px 8px;margin:0}
.invoice-toolbar .invoice-add{grid-column:2;grid-row:1;min-height:28px;padding:3px 8px}
.invoice-toolbar .invoice-legend{grid-column:1;grid-row:1;gap:3px 9px}
body.support-workroom.support-invoices-view .heading{min-height:0;margin-bottom:8px}
body.support-workroom.support-invoices-view .tools{padding:5px 8px;gap:8px;margin-bottom:5px}
#documents.charge-form{width:470px}
#documents.charge-form #document-fields{display:grid;gap:8px;margin-top:8px}
#documents.charge-form #document-fields>label{margin:0}
#documents.charge-form #document-fields>label[hidden],
#documents.charge-form #document-amount-label small,
#documents.charge-form #document-fields>label:has(#document-file)+small{display:none}
#documents.charge-form #charge-lines{grid-row:2}
#documents.charge-form #document-amount-label{grid-row:3}
#documents.charge-form #document-amount{width:120px;margin-left:auto;text-align:right}
#documents.charge-form #document-amount-label{display:flex;align-items:center;gap:8px}
#documents.charge-form #document-status{font-size:11px;margin:6px 0;color:#536d87}
#invoice-period:not([hidden]){display:flex;align-items:center;gap:6px}
.tools #invoice-month-select{min-width:62px}
#invoice-period button{min-width:26px;min-height:28px}
#invoice-year{min-width:4ch;text-align:center;font-variant-numeric:tabular-nums}
.invoice-list :is(th,td):last-child{min-width:366px}
.invoice-list .doc-strip{width:max-content;flex-wrap:nowrap}
.invoice-list .doc-strip>*{box-sizing:border-box;flex:0 0 28px}
.work-table.invoice-register{min-width:640px}
.invoice-register td:nth-child(2){width:35%;overflow-wrap:anywhere}

.support-workroom dialog .dialog-body>p:has(>strong+small){display:grid;gap:3px;margin:0 0 10px}
.support-workroom dialog .dialog-body>p>strong:has(+small){font:700 19px/1.25 var(--master-font);color:#173651;overflow-wrap:anywhere}
.support-workroom dialog .dialog-body>p>strong+small{font:500 11px/1.3 var(--master-font);color:#536d87}
#charge-document-identity{display:contents}
#documents.charge-form #charge-document-identity{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(95px,1fr);gap:10px;align-items:end}
#documents.charge-form #charge-document-identity>label{margin:0;font-weight:600}
.invoice-toolbar .invoice-legend{gap:5px 12px}
.invoice-toolbar .invoice-legend li{display:inline-flex;align-items:center;gap:5px}
.invoice-toolbar .invoice-legend strong{display:inline-grid;place-items:center;box-sizing:border-box;min-width:26px;height:20px;margin:0;padding:0 5px;border:1px solid #b9d0e4;border-radius:4px;background:#edf4fb;color:#234766;line-height:1}

.shipment-gate{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(65px,.7fr) minmax(75px,.8fr);gap:8px;align-items:end}.shipment-gate input,.shipment-gate select{min-width:0;width:100%}

.shipment-compact .shipment-columns{grid-template-columns:minmax(170px,1fr) minmax(150px,1fr) minmax(170px,1.12fr) minmax(160px,.85fr)}
.shipment-compact .shipment-columns>section{padding:7px 12px}
.shipment-compact .shipment-kv{min-height:18px}
.shipment-compact .shipment-columns>.shipment-totals{display:grid;align-content:center;justify-content:stretch;min-width:0;border-left:1px solid #dce6ef;background:#f0f5fa;color:#173651}
.shipment-totals table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}
.shipment-totals :is(th,td){padding:4px 5px;text-align:right;white-space:nowrap;font-size:11px}
.shipment-totals th{font-weight:600;color:#526d86}
.shipment-totals th[scope=row]{text-align:left}
.shipment-totals tbody td{font-weight:700}
.shipment-totals tbody small{font-size:10px;font-weight:400;color:#526d86}
.shipment-totals thead{border-bottom:1px solid #dce6ef}
.shipment-compact .shipment-overview{grid-template-columns:minmax(175px,1fr) minmax(0,3fr)}
.shipment-overview .shipment-totals table{max-width:480px}
.shipment-compact .shipment-invoice{justify-content:flex-start;gap:3px 8px;margin-top:4px}
.shipment-compact .shipment-invoice .invoice-number-link:not(:disabled){font-size:12px;background:#2563eb;color:#fff;border-color:#2563eb}
.shipment-compact .shipment-invoice .invoice-prefix:not(:disabled){background:#f58a00;color:#fff;border-color:#f58a00}
.shipment-compact .shipment-documents{padding:5px 12px;border-top:1px solid #dce6ef}
.shipment-compact .shipment-doc-grid{grid-template-columns:repeat(10,minmax(0,max-content));grid-template-rows:auto;grid-auto-flow:row;justify-content:space-between;gap:4px 9px}
.shipment-compact .shipment-doc-grid>div:nth-child(n+6){grid-column:auto}
.shipment-compact .shipment-doc-grid button{height:24px}
@media(max-width:1250px){.shipment-compact .shipment-doc-grid{grid-template-columns:repeat(5,minmax(0,1fr))}}
@media(max-width:850px){.shipment-compact .shipment-columns{grid-template-columns:repeat(2,minmax(0,1fr))}.shipment-compact .shipment-doc-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:480px){.shipment-compact .shipment-columns{grid-template-columns:1fr}.shipment-compact .shipment-doc-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}

#documents:not(.charge-form){width:410px;max-width:calc(100vw - 26px)}
.support-customers-view .work-table tbody tr+tr td{border-top:2px solid #b6cde0}
.order-tasks td:last-child{vertical-align:middle}
.order-tasks [data-tc-cell="sources"]{align-items:center}
.autocount-launch{flex:none}
.autocount-actions{display:flex;flex-wrap:wrap;gap:8px}
#autocount-data{width:100%;min-height:76px;resize:vertical;font:12px/1.4 monospace}
@media(min-width:1100px){
  .desk-task-table{overflow:clip;overflow-clip-margin:1px}
  .desk-task-table .order-tasks{min-width:0}
  .desk-task-table .order-tasks thead th{position:sticky;top:91px;z-index:3;box-shadow:0 1px #b6cde0}
