e:nowrap;overflow:hidden;text-overflow:ellipsis}.tc-list{padding:0;background:white}.tc-dialog button:disabled{opacity:.55;cursor:wait}.tc-dialog [data-tc-earlier]{display:block;margin:0 auto 10px}.tc-dialog [hidden]{display:none!important}
