/* Active Orders presentation only. Keep the original table geometry and handlers. */
#app:has(> .active-order-heading){font-family:'Purchase Dashboard Inter','Segoe UI','Microsoft YaHei',Arial,sans-serif;font-size:11px;color:#203047}
#app:has(> .active-order-heading) :is(button,input,select,textarea){font-family:inherit}
#app>.active-order-heading{display:flex;align-items:center;justify-content:space-between;gap:24px;position:static;min-height:56px;background:transparent;border:0;padding:0;margin-bottom:18px}
#app>.active-order-heading .heading{margin:0;min-width:0}
#app>.active-order-heading h1 .ao-title-zh{display:block;margin-top:2px;font-size:10px;font-weight:400;line-height:13px;color:#62758a}
#app>.active-order-heading .muted{display:none}
#app .ao-priorities{display:flex;flex-wrap:wrap;justify-content:flex-end;flex-shrink:0;gap:12px;padding:0;border:0}
#app .ao-priority{display:flex;align-items:center;justify-content:space-between;gap:16px;flex:0 0 238px;width:238px;min-width:238px;height:70px;padding:9px 14px;border:1px solid #b8ccdf;border-radius:5px;background:#fff;color:#203047;text-align:left;font-size:12px;font-weight:700;cursor:pointer;transition:transform .15s,box-shadow .15s}
#app .ao-priority small{display:block;margin-top:2px;color:inherit;font-size:11px;line-height:15px;font-weight:400}
#app .ao-priority b{display:inline-flex;align-items:center;justify-content:center;min-width:28px;height:28px;padding:2px 6px;border:1px solid transparent;border-radius:14px;background:#e7eef5;color:#173557;font-size:12px;line-height:20px}
#app .ao-priority.pending.has-work{background:#F58A00;border-color:#F58A00;color:#fff}
#app .ao-priority.incoming.has-work{background:#E51B2B;border-color:#E51B2B;color:#fff}
#app .ao-priority.has-work b{background:rgba(255,255,255,.18);border-color:rgba(255,255,255,.55);color:inherit}
#app .ao-priority:hover{transform:translateY(-1px);box-shadow:0 3px 8px #17355726}
#app .ao-priority:focus-visible{outline:2px solid #3766a2;outline-offset:3px}
#app .active-order-table .customer-shipment{margin-top:4px;font-size:10px;line-height:14px;font-weight:400;white-space:nowrap;color:#536b84}
#app:has(>.active-order-heading) .ao-move{font-size:11px;color:#3766a2;border-color:#b8ccdf;margin-left:auto}
#app:has(>.active-order-heading)>.tools{flex-wrap:wrap;gap:10px;min-height:30px;margin-bottom:12px;padding:10px 12px;background:#fff;border:1px solid #d5e1ec;border-radius:5px}
#app:has(>.active-order-heading)>.tools :is(select,.btn){height:30px;padding:4px 8px;font-size:11px}
#app>.ao-work-tabs{display:flex;gap:24px;margin:0 0 12px;border-bottom:1px solid #c5d5e5}
#app>.ao-work-tabs button{padding:7px 3px 8px;border:0;border-bottom:3px solid transparent;background:transparent;color:#536b84;font-size:12px;font-weight:600;cursor:pointer}
#app>.ao-work-tabs small{display:block;margin-top:2px;font-size:10px;line-height:14px;font-weight:400}
#app>.ao-work-tabs button[aria-pressed="true"]{border-bottom-color:#3766a2;color:#173557;font-weight:700}
#app>.ao-work-tabs button:is(:hover,:focus-visible){color:#173557;background:#e7eef5}
#app>.ao-allocation-tools :is(#activeCustomer,#supplierFilter,.ao-move,#visibleCount){display:none}
#app>.ao-allocation-tools:not(:has(.save-group:not([hidden]))){display:none}
@media(max-width:850px){#app>.active-order-heading{align-items:flex-start;flex-direction:column;gap:14px}#app .ao-priorities{justify-content:flex-start;flex-shrink:1}}
#app:has(>.active-order-heading) #activeCustomer{width:220px}
#app:has(>.active-order-heading) #allocationFilter{width:150px}
#app:has(>.active-order-heading) #supplierFilter{width:220px;min-width:0}
#app:has(>.active-order-heading) #stageFilter{width:200px}
#app>.active-order-heading h1{font-size:20px;font-weight:800;line-height:26px;color:#203047}
#app>.active-order-heading .muted{color:#536b84;font-size:10px}
#app>.active-order-heading .room-counts b{display:inline-flex;align-items:center;justify-content:center;min-width:22px;height:22px;padding:0 6px;border-radius:50%;background:#F58A00;color:#fff;font-size:11px;font-weight:700}
#app>.active-order-heading .room-counts b+b{background:#e7eef5;color:#173557}
#app:has(> .active-order-heading) .tools :is(input,select){font-size:11px;color:#203047;border-color:#b8ccdf}
#app .active-order-table th{background:#d2dfea;color:#203047;font-size:11px;font-weight:700}
#app .active-order-table{min-width:1320px}
#app .active-order-table :is(th,td){padding-left:8px;padding-right:8px}
#app .active-order-table #taskRows :is(.supplier-cell,.net-cost-cell){padding-left:8px;padding-right:8px}
#app .active-order-table th:nth-child(7),#app .active-order-table #taskRows .supplier-cell{padding-left:12px}
#app .active-order-table th:nth-child(8),#app .active-order-table #taskRows .net-cost-cell{padding-right:14px}
#app .active-order-table #taskRows .source-row>td.product-stack{border-left:0}
#app .active-order-table #taskRows .source-row>.product-stack{text-align:left;white-space:nowrap}
#app .active-order-table #taskRows .source-label{padding-left:0}
#app .active-order-table #taskRows .source-costing{display:inline;margin:0}
#app .active-order-table #taskRows .source-costing::before{content:' · '}
#app .active-order-table .ao-child-marker{display:inline-flex;vertical-align:middle;margin-left:6px;color:#7891a5;cursor:default}
#app .active-order-table .ao-child-marker svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
#app .active-order-table #clearSelection{padding:3px 4px}
#app .active-order-table #taskRows .handle{width:20px;height:26px;align-items:center;justify-content:center;border-radius:4px;color:#3766a2;font-size:20px;cursor:grab}
#app .active-order-table #taskRows .handle:is(:hover,:focus-visible){background:#dce8f4;color:#173557;outline:1px solid #9cb6ce}
#app .active-order-table #taskRows .handle:active{cursor:grabbing;background:#c7dbee}
#app .active-order-table .po-reference{white-space:nowrap;overflow-wrap:normal}
#app .active-order-table td{color:#203047}
#app .active-order-table .product-stack .itemname{font-size:11px;font-weight:700;color:#173557}
#app .active-order-table .product-stack :is(.barcode,.packing){font-size:10px;font-weight:400;color:#62758a}
#app .active-order-table .progress-node.complete{background:#2563EB;color:#fff}
#app .active-order-table .progress-node:not(.complete):not(.problem){background:#F58A00}
#app .active-order-table .progress-node.problem{background:#E51B2B;color:#fff}
#app .active-order-table :is(.supplier-head.complete,.po-reference.complete){color:#2563EB}
#app .active-order-table .supplier-head.pending{color:#F58A00}
#app .active-order-table .po-reference.pending{background:#F58A00;color:#fff;border-radius:4px}
#app .active-order-table .qty-mismatch{background:#F58A00!important;color:#fff!important}
#app .active-order-table .order-quantity>span.quantity-reference{cursor:default;text-decoration:none}
#app .active-order-table .received-quantity>:is(span.quantity-reference,.quantity-case){display:inline-flex;align-items:center;justify-content:center;box-sizing:border-box;height:19px;min-width:34px;padding:0 6px;font-family:inherit;font-size:11px;font-weight:600;line-height:14px;vertical-align:middle}
#app .active-order-table .received-quantity>span.quantity-reference{border:1px solid transparent;cursor:default;text-decoration:none}
#app .active-order-table .gp{white-space:nowrap}
#app .active-order-table :is(th,td):is(:nth-child(8),:nth-child(10),:nth-child(11),:nth-child(12)){text-align:right!important}
#app .active-order-table :is(th,td):nth-child(7){text-align:left!important}
#app .active-order-table :is(th,td):is(:nth-child(6),:nth-child(9)){text-align:center!important}
#app .active-order-table td:nth-child(11) .po-reference{text-align:right}
#app #taskRows .gp.gp-low{display:inline-block;padding:3px 7px;border-radius:12px;background:#E51B2B;color:#fff!important;line-height:14px}
#app .active-order-table #taskRows .gp-badge{display:inline-flex;align-items:center;gap:2px;vertical-align:middle;height:16px;margin-left:6px;padding:0 4px;border-radius:8px;font-size:9px;font-weight:600;line-height:14px;white-space:nowrap}
#app #taskRows .gp.gp-good{background:#2563EB;color:#fff!important}
#app .active-order-table .gp-badge svg{width:9px;height:9px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
#app .active-order-table .gp-badge svg circle{fill:currentColor;stroke:none}
#app .active-order-table .row-progress{justify-content:flex-end;gap:1.5px}
#app .active-order-table .progress-node{width:14px;height:14px;min-width:14px;color:#fff;font:700 9px/14px 'Purchase Dashboard Inter','Segoe UI',Arial,sans-serif;text-align:center}
#app .ao-progress-overview{margin:0 0 10px;padding:0;border:0;border-radius:0;background:transparent}
#app .ao-progress-caption{display:none}
#app .ao-progress-caption b{color:#203047;font-size:11px}
#app .ao-progress-stages{display:flex;flex-wrap:wrap;gap:10px 22px;align-items:center}
#app .ao-progress-stages button{display:flex;align-items:center;gap:8px;border:0;background:transparent;padding:0;text-align:left;font-size:11px;color:#173557}
#app .ao-progress-stages button>b{display:inline-flex;align-items:center;justify-content:center;flex:none;width:24px;height:24px;border-radius:50%;background:#3766a2;color:#fff;font-size:12px;font-weight:700}
#app .ao-progress-stages small{display:block;margin-top:3px;font-size:9px;color:#62758a}
#app .ao-progress-stages button:is(:hover,:focus-visible)>b{background:#244d82}
.pd-supplier-alerts .ao-stage-state{font-size:11px;font-weight:600}
.pd-supplier-alerts .ao-stage-state.complete{color:#2563EB}
.pd-supplier-alerts .ao-stage-state.pending{color:#b45a00}
.pd-supplier-alerts .ao-stage-state.problem{color:#E51B2B}
#modal .pd-supplier-alerts .pd-alert-open[data-source-po-task]{background:#F58A00;color:#fff}
body:has(#app>.active-order-heading) #taskSignals .task-signal{font-family:'Purchase Dashboard Inter','Segoe UI','Microsoft YaHei',Arial,sans-serif;background:#fff;border-color:#c5d5e5;color:#203047;font-size:11px}
body:has(#app>.active-order-heading) #taskSignals .task-signal b{display:inline-flex;align-items:center;justify-content:center;min-width:24px;height:24px;padding:0 6px;border-radius:50%;background:#e7eef5;color:#173557;font-size:12px;line-height:1;font-weight:700;font-variant-numeric:tabular-nums}
body:has(#app>.active-order-heading) #taskSignals .task-signal.has-work b{background:#F58A00;color:#fff}
body:has(#app>.active-order-heading) #taskSignals .task-signal.urgent.has-work b{background:#E51B2B;color:#fff}
body:has(#app>.active-order-heading) #taskSignals .task-signal b::before{content:none}
body:has(#app>.active-order-heading) #taskSignals .task-signal:is(:hover,:focus-visible){border-color:#376aa5;background:#f2f6fb}
/* One task scroll area; shared column header remains visible during row work. */
#app .active-task-scroll{max-height:none;overflow:visible;padding-right:0}
@media(width < 1400px){#app .active-task-scroll{overflow-x:auto}}
@media(min-width:1400px){#app>.panel:has(>.active-task-scroll){overflow:clip}}
#app .active-task-scroll .active-order-table{border-collapse:separate;border-spacing:0}
#app .active-task-scroll .active-order-table thead th{position:sticky;top:0;z-index:3;box-shadow:0 1px 0 #abc2d8}
#app .active-order-table .received-age{font-size:10px;font-weight:700}
#app .active-order-table .received-age :is(.task-received-date,.task-received-actor){font-weight:400}
@media(min-width:1400px){#app .active-task-scroll .active-order-table thead th{top:calc(var(--master-header-height,0px) + var(--master-nav-height,0px))}}
#app .active-task-scroll .active-order-table :is(th,td):nth-child(9),#app .active-task-scroll .active-order-table :is(th,td):nth-child(10){text-align:center!important}
#app .active-order-table .purchase-realloc{color:#E51B2B!important}

/* Compact task heading: existing row renderer, fixed columns and scroll handler are unchanged. */
#app>.active-order-heading.compact-task-heading{flex-direction:row;align-items:center;justify-content:flex-start;min-height:36px;gap:18px;margin:0 0 12px;padding:0}
#app>.compact-task-heading h1{margin:0;white-space:nowrap;font-size:20px;line-height:28px}
#app>.compact-task-heading h1 .ao-title-zh{display:inline;margin:0;font:inherit;color:inherit}
.compact-task-controls{display:flex;align-items:center;justify-content:flex-start;gap:10px;min-width:0}
#app>.compact-task-heading .ao-move{height:32px;white-space:nowrap;margin:0;padding:4px 9px}
.task-customer-picker{position:relative;min-width:270px;max-width:430px;color:#203047;font-size:11px}
.task-customer-picker summary,.task-customer-options button{display:flex;align-items:center;gap:8px;min-height:34px;padding:6px 10px;box-sizing:border-box;font:inherit;color:inherit}
.task-customer-picker summary{list-style:none;cursor:pointer;border:1px solid #b8ccdf;border-radius:4px;background:#fff}
.task-customer-picker summary::-webkit-details-marker{display:none}
.task-customer-name{flex:1;min-width:0;text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600}
.task-count-pill{display:inline-flex;align-items:center;justify-content:center;flex:none;box-sizing:border-box;min-width:25px;height:19px;padding:0 6px;border-radius:10px;font:600 11px/1 'Purchase Dashboard Inter','Segoe UI',Arial,sans-serif}
.task-count-pill.pending{background:#F58A00;color:#fff}.task-count-pill.issues{background:#E51B2B;color:#fff}.task-count-pill.neutral{background:#e7eef5;color:#536b84}
.task-picker-chevron{color:#3766a2;flex:none;font-size:16px;line-height:19px}
.task-customer-options{position:absolute;left:0;top:calc(100% + 4px);z-index:12;min-width:100%;width:max-content;max-width:min(430px,90vw);max-height:300px;overflow:auto;background:#fff;border:1px solid #b8ccdf;border-radius:4px;box-shadow:0 4px 12px #17355726;padding:4px}
.task-customer-options button{width:100%;border:0;background:transparent;cursor:pointer;border-radius:3px}
.task-customer-options button[aria-pressed=true]{background:#edf4fc;color:#2563eb}
.task-customer-options button:hover{background:#f1f5fa}
.task-customer-picker summary:focus-visible,.task-customer-options button:focus-visible{outline:2px solid #3766a2;outline-offset:1px}
#app:has(>.compact-task-heading)>.tools:not(:has(.save-group:not([hidden]))):not(:has([data-active-cancel])){display:none}
#app:has(>.compact-task-heading)>.tools .count{display:none}
#app:has(>.compact-task-heading){padding-top:14px;padding-bottom:0}
/* Ordinary child rows are white; selection, issue highlighting and drag feedback remain visible. */
#app .active-order-table.draft-column-layout #taskRows tr.source-row:not(.selected):not(.highlight):not(.grip-down)>td{background:#fff!important}
@media(max-width:760px){#app>.active-order-heading.compact-task-heading{flex-wrap:wrap;gap:8px}.compact-task-controls{flex:1}.task-customer-picker{min-width:210px;flex:1}#app>.compact-task-heading h1{font-size:18px}}
@media(max-width:480px){.compact-task-controls{width:100%}.task-customer-picker{max-width:none}.task-customer-options{max-width:calc(100vw - 36px)}}
/* Order quantities share the established 19px Rcv/Alloc capsule metrics. */
#app .purchase-tasks.active-order-table .order-quantity>span.quantity-reference{background:transparent!important;border:0;padding:0}
#app .purchase-tasks.active-order-table .order-quantity-slots>span.quantity-reference.purchase-info-total{display:inline-flex;align-items:center;justify-content:center;box-sizing:border-box;height:19px;min-width:28px;padding:0 8px;border:0;border-radius:12px;font-family:var(--master-font);font-size:11px;font-weight:600;font-variant-numeric:tabular-nums;font-feature-settings:normal;line-height:19px;letter-spacing:normal;white-space:nowrap;justify-self:start;cursor:default}

/* Child source identity follows its quantity; parent totals retain the shared capsule. */
#app .active-order-table .order-quantity-source{display:inline-flex;align-items:center;justify-content:flex-start;gap:8px;white-space:nowrap}
#app .active-order-table .order-quantity-source .ao-child-marker{margin:0;flex:none}
#app .purchase-tasks.active-order-table .order-quantity-source>span.quantity-reference.purchase-info-total{display:inline-flex;align-items:center;justify-content:center;box-sizing:border-box;height:19px;min-width:28px;padding:0 8px;border:0;border-radius:12px;font-family:var(--master-font);font-size:11px;font-weight:600;line-height:19px;letter-spacing:normal}
/* Keep the established PO/date/actor typography, with a compact three-line stack. */
#app .active-order-table #taskRows .po-reference.complete{padding:0;line-height:14px}
#app .active-order-table #taskRows :is(.po-entered-time,.po-entered-actor){margin-top:0;line-height:12px}

warehouse-room/workroom.css.source:
/* Warehouse-only desktop and handheld layout; shared department styles remain protected. */
#taskSignals{display:none!important}#whCompanyCaption{font-size:12px;color:#647f9a;margin:-7px 0 16px}.title-row{margin-bottom:10px;flex-direction:row;align-items:center}.warehouse-track{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:0;background:transparent;padding:0;gap:12px;margin-bottom:16px}.wh-card{display:flex;align-items:center;justify-content:space-between;min-height:64px;text-align:left;padding:12px 14px;border:1px solid #bed0e1;background:white;color:#173557;border-radius:5px}.wh-card b{font-size:12px}.wh-card small{display:block;margin-top:4px;font-size:11px}.wh-card>strong{font-size:18px}.wh-card.orange{background:#f58a00;color:white;border-color:#f58a00}.wh-card.red{background:#e51b2b;color:white;border-color:#e51b2b}.wh-card.selected{outline:2px solid #173557;outline-offset:2px}
