idth:30px}.wh-instruction{margin-top:4px}.wh-delivery .dm-open{margin-top:3px}.wh-picker{position:relative;min-width:280px;max-width:420px;margin:0}.wh-picker summary{list-style:none;display:flex;align-items:center;gap:8px;background:white;border:1px solid #bed2e1;border-radius:4px;padding:5px 9px;min-height:31px;color:#203047;font-size:11px}.wh-picker summary span{flex:1}.wh-picker>div{position:absolute;z-index:15;top:100%;width:100%;background:white;border:1px solid #bed2e1;box-shadow:0 5px 15px #17355722;max-height:300px;overflow:auto}.wh-picker button{display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;text-align:left;border:0;border-radius:0;padding:8px}.wh-picker button:hover{background:#edf4fb}.wh-picker small{display:block;padding:8px;color:#647e98}.wh-bubble{display:inline-flex;min-width:20px;height:20px;padding:0 4px;align-items:center;justify-content:center;border-radius:50%;font-size:11px;background:#f58a00;color:white}.wh-dispatch{padding:12px;background:white;border:1px solid #d2dfea;border-radius:5px}.wh-dispatch p{line-height:18px;color:#526b85}
